/**
 * With SWAP_WATCH_BUNDLE=false each swap is checked only at its own interval, as before bundling. In a file of its own, because settings are read once per process.
 */
// ----- Contents (generated by `npm run index` — do not edit) -----
// L20  follow()
// ----- end of contents -----

import test, { after } from 'node:test'
import assert from 'node:assert/strict'
import { useFakeSettings, stubMeson, makeWorld, swapId, sleep, texts, MOVING, DONE } from './helpers.mjs'

useFakeSettings({ SWAP_WATCH_BUNDLE: 'false' })
const { watchSwap, stopWatchingChannel } = await import('../src/watch.js')
const { getSwaps } = await import('../src/meson.js')
const { getTicket } = await import('../src/ticket-state.js')

after(() => { stopWatchingChannel('u1'); stopWatchingChannel('u2') })

/** Start following one swap in `world`'s ticket. */
async function follow (world, id) {
  const t = getTicket(world.channel.id)
  const entry = { n: 1, swapId: id, message: world.message(1, world.me), latest: (await getSwaps([id])).get(id) }
  t.swaps.push(entry)
  await watchSwap(t, entry)
}

test('an old swap waits for its own long interval, even while a newer swap is checked', async () => {
  const old = swapId('a')
  const fresh = swapId('b')
  const events = { [old]: MOVING, [fresh]: MOVING }
  stubMeson({ events, old: [old] })
  const first = makeWorld('u1')
  await follow(first, old)
  await sleep(1500)
  await follow(makeWorld('u2'), fresh)
  events[old] = DONE
  await sleep(2500)
  assert.equal(texts(first.posted).filter((x) => x.includes('Transaction Completed')).length, 0)
})
